SELECT CASE WHEN s.rating >= 4.4 THEN 'high' WHEN s.rating >= 2.6 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(ss.units) AS total_units FROM store_sales ss FULL OUTER JOIN products p ON ss.product_id = p.id LEFT JOIN suppliers s ON s.id = p.supplier_id WHERE ss.units BETWEEN 17 AND 30 GROUP BY CASE WHEN s.rating >= 4.4 THEN 'high' WHEN s.rating >= 2.6 THEN 'mid' ELSE 'low' END HAVING SUM(ss.units) > 230
